// Pose global.logo8_en_ligne (true/false) d'après le statut du nœud s7 in « LOGO8 ».
// Utilisé par les portes 🔒 des onglets 2, 3 et 4. Statut inconnu/en cours : drapeau inchangé.
// NB : texte de statut à confirmer sur votre installation (vert = en ligne, rouge = hors ligne).
const s = msg.status || {};
const t = String(s.text || '').toLowerCase();
const online  = s.fill === 'green' || t === 'online';
const offline = s.fill === 'red' || /offline|disconnect|error/.test(t);
if (online) global.set('logo8_en_ligne', true);
else if (offline) global.set('logo8_en_ligne', false);
msg.payload = global.get('logo8_en_ligne');
node.status({fill: online ? 'green' : (offline ? 'red' : 'yellow'), shape:'dot', text: t || '?'});
return msg;

// PORTE LOGO8 : dernier filet avant l'écriture dans le LOGO.
// 1) accepte uniquement un booléen (ou on/off/true/false/1/0) ;
// 2) bloque si le LOGO est connu HORS LIGNE (drapeau posé par « État LOGO8 »).
//    Si l'état est inconnu (undefined), on laisse passer pour ne pas figer l'installation.
let v = msg.payload;
if (typeof v === 'string') {
    const s = v.trim().toLowerCase();
    if (['on','true','1'].includes(s)) v = true;
    else if (['off','false','0'].includes(s)) v = false;
}
if (v === 1) v = true; else if (v === 0) v = false;
if (typeof v !== 'boolean') {
    node.status({fill:'red',shape:'ring',text:'rejeté : non booléen'});
    node.warn('Porte : valeur rejetée ' + JSON.stringify(msg.payload));
    return null;
}
if (global.get('logo8_en_ligne') === false) {
    node.status({fill:'red',shape:'ring',text:'bloqué : LOGO hors ligne'});
    node.warn('Porte : LOGO hors ligne, écriture bloquée');
    return null;
}
msg.payload = v;
node.status({fill:'green',shape:'dot',text:String(v)});
return msg;

